installation.script:
#!/bin/bash
set -euo pipefail
cd /mnt/server
test "$(uname -m)" = x86_64
work=$(mktemp -d /mnt/server/.cagent-install.XXXXXX)
trap 'rm -rf -- "$work"' EXIT
curl -fsSL --retry 3 https://shell.canp.ai/downloads/pro/v1.1.1/CAgent-1.1.1-linux-x64.tar.gz -o "$work/agent.tar.gz"
echo "e148bb617c0087ee122c904a50d93f6e7996abd5b5a75d031f27dc818369cf30  $work/agent.tar.gz" | sha256sum -c -
mkdir "$work/runtime"
tar -xzf "$work/agent.tar.gz" -C "$work/runtime"
test -x "$work/runtime/cagent"
if [ ! -d .cagent-1.1.1 ]; then mv "$work/runtime" .cagent-1.1.1; fi
cat > "$work/start.cjs" <<'CAGENT_BOOT'
'use strict';
const {spawn, execFile} = require('node:child_process');
const {promisify} = require('node:util');
const {setTimeout: delay} = require('node:timers/promises');
const agent='/home/container/.cagent-1.1.1/cagent';
process.umask(0o077);
process.env.CSHELL_AGENT_DATA='/home/container/.cshell-agent';
async function call(args, payload) {
  const output = await new Promise((resolve,reject)=>{
    const proc=execFile(agent,args,{timeout:20000},(err,out)=>err?reject(new Error('CAgent '+args[0]+' failed')):resolve(out));
    proc.stdin.on('error',()=>{});
    proc.stdin.end(JSON.stringify(payload??{}));
  });
  return JSON.parse(output);
}
async function main(){
  const os=require('node:fs').readFileSync('/etc/os-release','utf8');
  if(!/^ID=ubuntu$/m.test(os)||!/^VERSION_ID="24.04"$/m.test(os))throw Error('Ubuntu 24.04 required');
  const port=Number(process.env.SERVER_PORT);
  if(!Number.isInteger(port)||port<1||port>65535)throw Error('Invalid port');
  let password=process.env.CAGENT_PASSWORD;
  const id=process.env.CSHELL_RENTAL_ID, token=process.env.CSHELL_ENROLL_TOKEN;
  for(const key of ['CAGENT_PASSWORD','CSHELL_RENTAL_ID','CSHELL_ENROLL_TOKEN']) delete process.env[key];
  const child=spawn(agent,['run'],{stdio:['ignore','inherit','inherit']});
  const exited=new Promise(resolve=>child.on('exit',resolve));
  process.on('SIGTERM',()=>child.kill('SIGTERM'));
  process.on('SIGINT',()=>child.kill('SIGINT'));
  try{
    let state;
    for(let n=0;n<60&&!state;n++){
      if(child.exitCode!==null||child.signalCode)throw Error('CAgent exited');
      try{state=await call(['status']);}catch{await delay(500);}
    }
    if(!state)throw Error('CAgent control unavailable');
    if(!state.passwordConfigured){
      if(!password||password.length<24)throw Error('Set an instance-specific CAGENT_PASSWORD');
      await call(['call','client.access'],{password,shells:['bash','sh']});
    }
    password=undefined;
    if(!state.running||state.port!==port||state.bind!=='0.0.0.0'){
      if(state.running)await call(['stop']);
      await call(['start'],{bind:'0.0.0.0',port});
    }
    state=await call(['status']);
    if(!state.running||state.port!==port)throw Error('Listener unavailable');
    console.log('CAgent ready',state.deviceId,state.fingerprint);
    while(id&&token&&child.exitCode===null&&!child.signalCode){
      try{
        const res=await fetch('https://shell.canp.ai/api/v1/rentals/enroll',{method:'POST',redirect:'error',signal:AbortSignal.timeout(10000),headers:{'Content-Type':'application/json'},body:JSON.stringify({id,token,identity:{deviceId:state.deviceId,fingerprint:state.fingerprint}})});
        if(res.ok && (await res.json()).ok)break;
      }catch{}
      await Promise.race([exited,delay(15000,undefined,{ref:false})]);
    }
    process.exitCode=await exited || 0;
  }finally{if(child.exitCode===null&&!child.signalCode)child.kill('SIGTERM');}
}
main().catch(err=>{console.error(err.message);process.exitCode=1;});
CAGENT_BOOT
mv -f "$work/start.cjs" .cagent-start.cjs
